(async () => {
  const out = {};
  let n = 0;
  const take = async () => { const l = await log(); const r = l.slice(n); n = l.length; return r; };
  await sleep(1200);
  out.load = await take();
  out.s0 = {rs: v.readyState, ns: v.networkState, dur: v.duration, buf: rng(v.buffered)};
  v.muted = true;
  v.play().catch(e => out.playError = e.name);
  await sleep(900);
  out.afterPlay = {rs: v.readyState, ns: v.networkState, ct: cq(v), buf: rng(v.buffered), paused: v.paused};
  v.pause();
  out.play = await take();
  const d = v.duration;
  if (d > 0) {
    v.currentTime = d * 0.6;
    await once(v, 'seeked', 3000);
    await sleep(700);
  }
  out.afterSeek = {rs: v.readyState, ct: cq(v), buf: rng(v.buffered), seeking: v.seeking};
  out.seek = await take();
  v.currentTime = 0.1;
  await once(v, 'seeked', 3000);
  await sleep(500);
  out.seekBack = await take();
  return out;
})()

